let novoConteudo = header;
novoConteudo += 'const COFEN_ARTIGOS = [\n';

for (let i = 0; i < A.length; i++) {
  const a = A[i];
  const virgula = i < A.length - 1 ? ',' : '';
  novoConteudo += '  {\n';
  novoConteudo += '    id: "' + a.id + '", artigo: "' + a.artigo + '", titulo: "' + a.titulo + '",\n';
  novoConteudo += '    texto: "' + a.texto.replace(/"/g, '\\"') + '",\n';
  novoConteudo += '    explicacao: "' + a.explicacao.replace(/"/g, '\\"') + '",\n';
  novoConteudo += '    capitulo: "' + a.capitulo + '"\n';
  novoConteudo += '  }' + virgula + '\n';
}

novoConteudo += '];\n\n';
novoConteudo += resto;

fs.writeFileSync(dataPath, novoConteudo, 'utf8');
console.log('data.js atualizado com sucesso!');
